head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > removeColumnFilterAll]<br/>DataList 모듈에 적용된 모든 필터/정렬 조건을 제거합니다.",
    "validation" : [
        "DataList 모듈에 적용된 모든 정렬 조건을 제거합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strGridView = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataList ' + strNameSpace + ' id="target1" baseNode="list" repeatNode="map">';        
    strTarget += '<w2:columnInfo>';
    strTarget += '<w2:column id="col_text" name="name1" dataType="text"></w2:column>';
    strTarget += '<w2:column id="col_number" name="name1" dataType="number"></w2:column>';
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<w2:row>';
    strTarget += '<col_text><![CDATA[B]]></col_text>';
    strTarget += '<col_number><![CDATA[8]]></col_number>';    
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col_text><![CDATA[A]]></col_text>';
    strTarget += '<col_number><![CDATA[9]]></col_number>';    
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col_text><![CDATA[A]]></col_text>';
    strTarget += '<col_number><![CDATA[2]]></col_number>';    
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col_text><![CDATA[B]]></col_text>';
    strTarget += '<col_number><![CDATA[9]]></col_number>';    
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col_text><![CDATA[B]]></col_text>';
    strTarget += '<col_number><![CDATA[5]]></col_number>';    
    strTarget += '</w2:row>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataList>';    

    $p.data.create(strTarget);

    // gridView 생성
    strGridView += '<w2:gridView ' + strNameSpace + ' sortable="true" rowStatusVisible="true" checkAllType="false" id="gridView1" dataList="target1" style="width:500px;height:300px;" ev:onsort="scwin.gridView1_onsort">';
    strGridView += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strGridView += '<w2:header style="" id="header1">';
    strGridView += '<w2:row style="" id="row1">';
    strGridView += '<w2:column width="120" style="" inputType="text" id="column1" value="col_text"></w2:column>';
    strGridView += '<w2:column width="120" style="" inputType="number" id="column2" value="col_number"></w2:column>';
    strGridView += '</w2:row>';
    strGridView += '</w2:header>';
    strGridView += '<w2:gBody style="" id="gBody1">';
    strGridView += '<w2:row style="" id="row2">';
    strGridView += '<w2:column width="120" style="" id="col_text" value=""></w2:column>';    
    strGridView += '<w2:column width="120" style="" id="col_number" value=""></w2:column>';    
    strGridView += '</w2:row>';
    strGridView += '</w2:gBody>';
    strGridView += '</w2:gridView>';    

    // gridView 생성
    scwin["gridView1"] = await $p.dynamicCreate(
        "gridView1",
        "gridView",
        strGridView,
        grp_comp
    );    

    scwin.btn_multisort_onclick();
}   



scwin.btn_getAllFilteredJSON_onclick = function (e) {
    let rtn = target1.getAllFilteredJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_multisort_onclick = function (e) {
    let options = {};
	options.sortIndex = "col_text col_number";
    options.sortOrder = "-1 1";

    target1.multisort(options);

    scwin.btn_getAllFilteredJSON_onclick();
};



scwin.btn_removeColumnFilterAll_onclick = function (e) {
    target1.removeColumnFilterAll();

    scwin.btn_getAllFilteredJSON_onclick();
}
